import std.io

pub type AppError = Failed(String)

record Fetcher { seed: Int64 }

impl Fetcher {
    fn fetch(self) -> Result<Int64, AppError> {
        return Ok(self.seed)
    }
}

pub fn main() effect io -> Result<(), AppError> {
    let f = Fetcher { seed: 7 }
    let v = f.fetch()?
    io.println("v ${v}")
    return Ok(())
}
